head.script:
// https://inswave01.atlassian.net/browse/WAEA-1195



// 테스트 설명, 유효성 값 설정
//  ★ _1 : @description 부가 문구 + options 파라미터 공통 + 기본 옵션(fileName, extension, sheetName, pwd) + 마지막 @spec. description 은 분리 샘플 공통.
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "JDK 1.5 이상에서 사용할 수 있으며 GridView 에 DataList 가 바인딩 되어 있어야 합니다.",
        "options(필수) 파라미터로 Excel 파일 다운로드 옵션을 객체로 설정합니다.",
        "다운로드 옵션을 기본값으로만 설정할 경우 빈 객체({})로 설정해야 합니다.",
        "fileName(선택) 파라미터로 다운로드될 Excel 파일명을 설정합니다.",
        "fileName(선택) 파라미터에서 확장자를 생략하거나 파라미터값 생략 시 파일명의 확장자는 extension 파라미터값이 적용됩니다.",
        "fileName(선택) 파라미터를 생략하면 기본값 'excel' 이 적용됩니다.",
        "extension(선택) 파라미터로 다운로드될 Excel 파일의 확장자를 설정합니다.",
        "extension(선택) 파라미터는 fileName 파라미터를 생략하거나 확장자를 생략했을때 적용됩니다.",
        "extension(선택) 파라미터를 생략하면 기본값 'xls' 가 적용됩니다.",
        "sheetName(선택) 파라미터로 다운로드될 Excel 파일의 시트명을 설정합니다.",
        "sheetName(선택) 파라미터를 생략하면 기본값 'sheet' 가 적용됩니다.",
        "pwd(선택) 파라미터로 Excel 파일의 암호를 설정합니다.",
        "pwd(선택) 파라미터의 암호는 BASE64 로 인코딩한 뒤 전달해야 하며, 서버측 websquare.xml 설정과 POI 3.10 이상이 필요합니다.",
        "pwd(선택) 파라미터를 생략하면 기본값인 빈 문자열이 적용되어 암호가 설정되지 않습니다.",
        "advancedExcelDownload() 메소드는 Excel 다운로드 완료 또는 실패 시 별도의 이벤트를 제공하지 않으므로 onSuccessCallback, onFailureCallback 파라미터의 콜백 함수를 사용해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n- 파일명 항목의 download_grid 는 확장자가 없는 값, download_grid.xls 는 확장자를 포함한 값임\n- 암호 항목의 값 MTIzNA== 는 암호 1234 를 BASE64 로 인코딩한 값임\n[절차]\n1. par 옵션(fileName / extension / sheetName / pwd) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭한다\n[확인]\n- 결과창에 전달한 options 객체와 서버로 실제 전달된 파일명 / 시트명 / 암호가 출력됨\n- 다운로드된 파일의 이름과 확장자, 파일을 열었을 때의 시트명과 암호 적용 여부를 확인\n- 모든 항목을 미설정으로 두면 빈 객체가 전달되어 각 옵션이 기본값으로 동작함"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 모든 파라미터가 미설정이면 빈 객체({}) 가 전달된다.
scwin.buildOptions = function () {
    let options = {};

    let vFileName = par_fileName.getValue();
    if (vFileName !== "") options.fileName = vFileName;

    let vExtension = par_extension.getValue();
    if (vExtension !== "") options.extension = vExtension;

    let vSheetName = par_sheetName.getValue();
    if (vSheetName !== "") options.sheetName = vSheetName;

    let vPwd = par_pwd.getValue();
    if (vPwd !== "") options.pwd = vPwd;

    return options;
}



// 서버로 전송된 XML 문자열에서 지정한 항목의 값을 읽는다.
scwin.getSentValue = function (strSent, strKey) {
    let objMatch = strSent.match(new RegExp("<data hashkey='" + strKey + "' value='([^']*)'/>"));
    return (objMatch === null) ? "(전달되지 않음)" : objMatch[1];
}



// advancedExcelDownload 실행
//  · 엔진이 호출 중 options 객체에 내부 키(cellInfo, scope, isBasicCol 등)를 덧붙이므로 전달값 문자열은 호출 전에 만들어 둔다.
//  · 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//    호출 구간에만 form 전송을 가로채 서버로 실제 전달되는 값(파일명 / 시트명 / 암호)을 읽는다.
//  · 다운로드 완료 또는 실패 시 발생하는 이벤트가 없으므로 완료 여부는 콜백 함수로만 확인한다.
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let options = scwin.buildOptions();
    let strOptions = JSON.stringify(options);

    options.onSuccessCallback = function (strUrl, objData) {
        bottom.setReturnValue("onSuccessCallback 실행 : Excel 다운로드 완료");
    };
    options.onFailureCallback = function (strUrl, objData) {
        bottom.setReturnValue("onFailureCallback 실행 : Excel 다운로드 실패 (" + ((objData && objData.errorCode) ? objData.errorCode : "") + ")");
    };

    bottom.setReturnValue("전달한 options : " + strOptions);

    let fnSubmit = HTMLFormElement.prototype.submit;
    let fnRestore = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
    HTMLFormElement.prototype.submit = function () {
        fnRestore();

        let objHidden = this.querySelector("input[name='xmlValue']");
        let strSent = (objHidden === null) ? "" : objHidden.value;
        bottom.setReturnValue("서버로 전달된 파일명 : " + scwin.getSentValue(strSent, "fileName") + " / 시트명 : " + scwin.getSentValue(strSent, "sheetName") + " / 암호 : " + scwin.getSentValue(strSent, "pwd"));

        return fnSubmit.apply(this, arguments);
    };
    setTimeout(fnRestore, 5000);

    target1.advancedExcelDownload(options);
}
